export default {
  namespaced: true,

  state() {
    return {
      models: [],
      selectedModel: null,
      selectedModelColor: null,
      modelsLoading: false,
      modelsLoaded: false,
      modelsError: false,
    };
  },

  mutations: {
    setModels(state, payload) {
      const nextModels = Array.isArray(payload) ? payload : [];
      const selectedId = state.selectedModel?.id;

      state.models = nextModels;
      state.selectedModel =
        nextModels.find((model) => model.id == selectedId) ||
        nextModels[0] ||
        null;
      state.selectedModelColor = state.selectedModel?.images?.[0] || null;

      if (state.selectedModel) {
        this.dispatch("order/calculatePrice");
      }
    },
    setModelsLoading(state, payload) {
      state.modelsLoading = Boolean(payload);
    },
    setModelsLoaded(state, payload) {
      state.modelsLoaded = Boolean(payload);
    },
    setModelsError(state, payload) {
      state.modelsError = Boolean(payload);
    },
    pushModel(state, payload) {
      state.models.push(payload);
    },
    deleteModel(state, { id }) {
      state.models = state.models.filter((m) => m.id != id);
      if (state.selectedModel && state.selectedModel.id == id) {
        this.commit("product/setModels", state.models);
      }
    },
    setSelectedModel(state, payload) {
      state.selectedModel = payload || null;
      state.selectedModelColor = state.selectedModel?.images?.[0] || null;
      if (state.selectedModel) {
        this.dispatch("order/calculatePrice");
      }
    },
    setSelectedModelColor(state, payload) {
      state.selectedModelColor = payload;
    },
    selectFristModel(state) {
      this.commit("product/setSelectedModel", state.models[0] || null);
    },
  },

  getters: {
    selectedModelColorUrl(state, getters, rootState) {
      return state.selectedModelColor
        ? state.selectedModelColor[rootState.canvas.mode].url
        : null;
    },
  },
};
