<template>
  <div class="q-pa-md row items-start mode-selector">
    <div v-if="selectedModelColor" class="selectors-wrapper">
      <div
        @click="setMode('front')"
        :class="{ active: mode == 'front' }"
        class="selector-item"
      >
        <img
          v-if="selectedModelColor.front && selectedModelColor.front.url"
          :src="selectedModelColor.front.url"
          alt=""
        />
      </div>
      <div
        v-if="selectedModelColor.back && selectedModelColor.back.url"
        @click="setMode('back')"
        :class="{ active: mode == 'back' }"
        class="selector-item"
      >
        <img :src="selectedModelColor.back.url" alt="" />
      </div>
    </div>
  </div>
</template>

<script>
import { mapState } from "vuex";
import { mapMutations } from "vuex";

import CanvasService from "@/services/canvas";

export default {
  name: "ModeSelector",

  computed: {
    ...mapState("canvas", ["mode"]),
    ...mapState("product", ["selectedModel", "selectedModelColor"]),
  },

  watch: {
    mode() {
      this.changeMode();
    },
    selectedModel() {
      if (!this.selectedModelColor || typeof this.selectedModelColor.back === "undefined") {
        this.setMode("front");
      }
    },
  },

  methods: {
    ...mapMutations("canvas", ["setMode"]),

    changeMode() {
      CanvasService.changeMode();
    },
  },
};
</script>

<style lang="scss">
.mode-selector {
  position: absolute;
  z-index: 9;
  top: 12px;
  left: 12px;
  padding: 6px;
  background: rgba(6, 10, 22, 0.85);
  border-radius: 12px;
  border: 1px solid rgba(130, 200, 255, 0.2);
  box-shadow: 0 0 18px rgba(0, 230, 255, 0.18);
  backdrop-filter: blur(6px);

  .selector-item {
    background: rgba(7, 12, 22, 0.8);
    border: 1px solid rgba(126, 234, 255, 0.2);
    border-radius: 5px;
    margin-bottom: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    @media (max-width: $breakpoint-sm) {
      float: left;
      margin-right: 10px;
    }

    &.active {
      border-color: $primary;
      box-shadow: 0 0 16px rgba(0, 230, 255, 0.35);
    }

    img {
      max-width: 60px;
      border-radius: inherit;
    }
  }
}
</style>
