<template>
  <q-dialog v-model="dialog" persistent>
    <q-card>
      <q-card-section class="row items-center">
        <q-spinner
          v-if="modelsLoading"
          color="primary"
          size="2em"
          class="q-mr-md"
        />
        <q-icon
          v-else-if="modelsError"
          name="error"
          color="negative"
          size="2em"
          class="q-mr-md"
        />
        <q-icon
          v-else
          name="info"
          color="primary"
          size="2em"
          class="q-mr-md"
        />
        <div class="text-body1">
          {{ message }}
        </div>
      </q-card-section>

      <q-card-actions v-if="!modelsLoading" align="right">
        <q-btn
          v-if="modelsError"
          color="primary"
          no-caps
          :label="$t('label.retry')"
          @click="retry"
        />
        <q-btn
          flat
          color="primary"
          no-caps
          :label="$t('label.catalog')"
          @click="openCatalog"
        />
        <q-btn
          color="primary"
          no-caps
          :label="$t('label.createOwn')"
          @click="openCustomModel"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script>
import { mapState } from "vuex";
import { mapMutations } from "vuex";

export default {
  name: "InitModal",

  computed: {
    ...mapState("app", ["user"]),
    ...mapState("product", [
      "models",
      "modelsLoading",
      "modelsLoaded",
      "modelsError",
    ]),

    message() {
      if (this.modelsLoading) {
        return this.$t("text.loadingAppState");
      }
      if (this.modelsError) {
        return this.$t("text.modelsLoadFailed");
      }
      return this.$t("text.modelsEmpty");
    },

    showEmptyState() {
      return (
        this.modelsLoaded &&
        !this.modelsLoading &&
        !this.modelsError &&
        this.models.length === 0
      );
    },

    dialog: {
      get() {
        return this.modelsLoading || this.modelsError || this.showEmptyState;
      },
      set() {},
    },
  },

  methods: {
    ...mapMutations("app", [
      "setCatalogModalOpened",
      "setCustomProductModalOpened",
      "setAuthModalOpened",
    ]),

    openCatalog() {
      this.setCatalogModalOpened(true);
    },

    openCustomModel() {
      if (this.user) {
        this.setCustomProductModalOpened(true);
      } else {
        this.setAuthModalOpened(true);
      }
    },

    retry() {
      this.$emit("retry");
    },
  },
};
</script>
