<template>
  <q-layout view="lHh Lpr lFf" class="designer-shell">
    <q-header elevated class="glossy designer-header">
      <q-toolbar class="bg-primary text-white designer-toolbar">
        <q-toolbar-title> Print Designer</q-toolbar-title>
        <div class="row items-center">
          <q-btn
            color="accent"
            text-color="purple"
            :label="$i18n.locale"
            class="q-mr-sm"
          >
            <q-menu :offset="[0, 5]">
              <q-list style="min-width: 100px">
                <q-item
                  v-for="locale in $i18n.availableLocales"
                  :key="locale"
                  clickable
                  v-close-popup
                  @click="setLanguage(locale)"
                >
                  <q-item-section class="text-uppercase">
                    {{ locale }}
                  </q-item-section>
                  <q-item-section v-if="locale === $i18n.locale">
                    <q-icon name="done" color="purple" size="20px" />
                  </q-item-section>
                </q-item>
              </q-list>
            </q-menu>
          </q-btn>

          <q-btn v-if="user" round>
            <q-avatar round color="accent" text-color="purple">
              {{ user.name[0] }}
            </q-avatar>
            <q-menu :offset="[0, 5]">
              <q-list>
                <q-item clickable v-close-popup @click="logout">
                  <q-item-section>{{ $t("label.logout") }}</q-item-section>
                </q-item>
              </q-list>
            </q-menu>
          </q-btn>

          <q-btn
            v-else
            @click="setAuthModalOpened(true)"
            no-caps
            color="accent"
            text-color="purple"
            :label="$t('label.login')"
          />
        </div>
      </q-toolbar>
    </q-header>

    <q-page-container>
      <q-page padding class="designer-page">
        <div class="row designer-layout">
          <div class="col-md-3 col-sm-12 sm-full-width designer-panel">
            <LayersPanel />
          </div>
          <div class="col-md-6 col-sm-12 canvas-column designer-canvas-col">
            <div class="canvas-designer designer-card">
              <ModeSelector />
              <div class="flex flex-center canvas-wrapper">
                <canvas ref="canvas"></canvas>
              </div>
            </div>
          </div>
          <div class="col-md-3 col-sm-12 order-sm-last sm-full-width designer-panel">
            <ControlsPanel />
          </div>
        </div>
      </q-page>
    </q-page-container>
  </q-layout>

  <InitModal @retry="loadProductModels(user?.id)" />
  <AuthModal />
  <CatalogModal />
  <CustomProductModal />
</template>

<script>
import { mapState } from "vuex";
import { mapGetters } from "vuex";
import { mapMutations } from "vuex";
import { fabric } from "fabric";
import { syncLanguage } from "./locales";

import UserService from "@/services/user";
import OrderService from "@/services/order";
import CanvasService from "@/services/canvas";
import ProductService from "@/services/product";

import WebFont from "webfontloader";
import WebFontConfig from "@/WebFontConfig";

import LayersPanel from "@/components/Layers/Panel";
import ModeSelector from "@/components/Controls/ModeSelector";
import ControlsPanel from "@/components/Controls/Panel";

import InitModal from "@/components/Modals/Init";
import AuthModal from "@/components/Modals/Auth";
import CatalogModal from "@/components/Modals/Catalog";
import CustomProductModal from "@/components/Modals/CustomProduct";

export default {
  name: "LayoutDefault",

  inject: ["ctx"],

  components: {
    LayersPanel,
    ControlsPanel,
    ModeSelector,
    InitModal,
    AuthModal,
    CatalogModal,
    CustomProductModal,
  },

  mounted() {
    this.loadProductModels(this.user?.id);
    this.loadPricing();

    const ref = this.$refs.canvas;
    this.ctx.canvas = new fabric.Canvas(ref, {
      selection: false,
      width: 600,
      height: 560,
      allowTouchScrolling: true,
    });

    this.ctx.canvas.on("before:selection:cleared", () => {
      this.resetSelectedLayer();
      this.setControlTab("product");
    });

    this.ctx.canvas.on("selection:created", (event) => {
      this.handleSelection(event);
    });

    this.ctx.canvas.on("selection:updated", (event) => {
      this.handleSelection(event);
    });

    this.ctx.canvas.on("object:modified", (event) => {
      if (event.action === "scale" || event.action === "rotate") {
        this.selectedLayer.dirty = true;
      }
    });

    this.ctx.canvas.on({
      "object:added": () => this.syncLayers(this.ctx.canvas.getObjects()),
      "object:removed": () => this.syncLayers(this.ctx.canvas.getObjects()),
    });

    this.ctx.canvas.on("mouse:dblclick", ({ target}) => {
      if(target && target.type === 'image'){
       CanvasService.prepareCrop(target)
      }
    })

    document.addEventListener("keydown", (e) => {
      if (
        ["Delete", "Backspace"].includes(e.key) &&
        this.selectedLayer.layerId
      ) {
        if (document.querySelector(".layer-text-field")?.matches(":focus"))
          return;
        CanvasService.removeLayer(this.selectedLayer);
      }
    });

    WebFont.load(WebFontConfig);
  },

  computed: {
    ...mapState("app", ["user"]),
    ...mapState("canvas", ["selectedLayer"]),
    ...mapState("product", ["selectedModelColor"]),
    ...mapGetters("product", ["selectedModelColorUrl"]),
  },

  watch: {
    user(newUser) {
      this.loadProductModels(newUser?.id);
    },
    selectedModelColorUrl(url) {
      if (url) CanvasService.drawSelectedModel();
    },
  },

  methods: {
    ...mapMutations("app", [
      "setUser",
      "setControlTab",
      "setAuthModalOpened",
      "setCatalogModalOpened",
    ]),
    ...mapMutations("order", ["setPricing"]),
    ...mapMutations("canvas", [
      "syncLayers",
      "setSelectedLayer",
      "resetSelectedLayer",
    ]),
    ...mapMutations("product", [
      "setModels",
      "setModelsLoading",
      "setModelsLoaded",
      "setModelsError",
    ]),

    handleSelection(event) {
      let layer = event.selected[0];
      if (this.selectedLayer.layerId != layer.layerId) {
        this.setSelectedLayer(layer);
        this.setControlTab("object");
      }
    },

    async loadPricing() {
      let prices = await OrderService.getPrices();
      if (prices) {
        this.setPricing(prices);
      }
    },

    async loadProductModels(userId) {
      this.setModelsLoading(true);
      this.setModelsLoaded(false);
      this.setModelsError(false);

      let models = null;
      try {
        models = await ProductService.getModels(userId);
      } catch (error) {
        models = null;
      }

      if (Array.isArray(models)) {
        this.setModels(models);
      } else {
        this.setModels([]);
        this.setModelsError(true);
      }

      this.setModelsLoading(false);
      this.setModelsLoaded(true);
    },

    async logout() {
      await UserService.logout();
      window.location.reload();
    },

    setLanguage(lang) {
      this.$i18n.locale = lang;
      syncLanguage(lang);
    },
  },
};
</script>

<style lang="scss">
