  --pd-surface: #05070d;
  --pd-surface-alt: rgba(6, 10, 22, 0.7);
  --pd-panel: rgba(7, 11, 22, 0.78);
  --pd-border: rgba(130, 200, 255, 0.2);
  --pd-border-strong: rgba(126, 234, 255, 0.48);
  --pd-shadow: 0 18px 42px rgba(0, 0, 0, 0.45);
  --pd-shadow-soft: 0 12px 30px rgba(0, 0, 0, 0.35);
  --pd-radius: 16px;
  --pd-radius-sm: 12px;
  --pd-canvas-bg: #0a0f1c;
  --pd-ink-strong: #f5fbff;
  --pd-ink-soft: #9fb6d8;
  --pd-glow: #6ee9ff;
  --pd-accent: #00e6ff;
  --pd-accent-soft: rgba(0, 230, 255, 0.25);
  --pd-accent-strong: rgba(0, 230, 255, 0.6);
  color: var(--pd-ink-strong);
}

