  background: linear-gradient(90deg, rgba(8, 14, 28, 0.95), rgba(6, 10, 20, 0.9));
  border-bottom: 1px solid var(--pd-border);
  position: relative;
}

.designer-toolbar::after {
  content: "";
  position: absolute;
  left: 12%;
  right: 12%;
  bottom: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--pd-border-strong), transparent);
  opacity: 0.85;
}

.designer-toolbar .q-toolbar__title {
  font-weight: 700;
  letter-spacing: 0.02em;
}

