  background:
    radial-gradient(760px 320px at 12% -10%, rgba(0, 230, 255, 0.16), transparent 60%),
    radial-gradient(900px 360px at 90% -15%, rgba(255, 98, 229, 0.14), transparent 55%),
    #03040a;
  min-height: calc(100vh - 64px);
}

